const money=(n,d=2)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n||0));
const num=n=>new Intl.NumberFormat('en-US').format(Number(n||0));
const pct=n=>`${Number(n||0).toFixed(1)}%`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const short=v=>String(v||'').length>18?`${String(v).slice(0,9)}…${String(v).slice(-6)}`:String(v||'');
const timeAgo=m=>m<1?'just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`;
const stamp=m=>new Date(Date.now()-m*60000).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const statusTone=s=>/fail|mismatch|rejected|exception|review|stuck|reversed/i.test(s)?'failed':/pending|processing|open|settling|submitted|partial|awaiting/i.test(s)?'pending':/active|owned|verified|confirmed|complete|settled|accepted|matched|paid|qualified|approved|closed/i.test(s)?'success':'info';
const railClass=r=>String(r||'internal').toLowerCase().replace(/[^a-z]/g,'');

