addEvents('Vault','Operational',['Item entered vault','Ownership created','365-day clock started','Pending liquidation quote updated','Item listed','Item repriced','Listing price removed','Platform buyout accepted','Vault cashout completed','Physical redemption requested','Item sent to user','Item received from user','Vault item expired','Auto Credit Back executed','Item removed from vault'],'Vault lifecycle must retain initial FMV, live FMV, funding rail and 365-day state.');
addEvents('Marketplace','Operational',['Offer-only inventory created','Listing created','Listing repriced','Listing price removed','Listing cancelled','Listing closed','Offer sent','Offer received','Offer countered','Counter received','Offer accepted','Offer declined','Offer cancelled','Offer expired','Buy Now initiated','Buy Now completed','Marketplace sale completed','Buyer funds debited','Seller proceeds credited','Marketplace fee charged','Ownership transferred','Marketplace settlement failed','Marketplace settlement reversed'],'One sale should appear as a correlated chain rather than one opaque row.');
addEvents('Stocks','Operational',['Stock outcome revealed','Stock buy order submitted','Stock buy partially filled','Stock buy filled','Stock buy failed','Acquisition price captured','Shares acquired','Stock lot assigned','Position consolidated','Portfolio value updated','Unrealized P&L updated','Partial sale requested','Full sale requested','Stock sell submitted','Stock sell partially filled','Stock sell filled','Stock sell failed','Sale proceeds credited','Stock position transferred','Stock lot depleted','Stock position closed'],'Stock principal belongs to the user after assignment; Observe tracks custody plus execution lifecycle.');
addEvents('Fees','Financial',['Chain gas fee incurred','Stock buy execution fee','Stock sell execution fee','Stock transfer fee','Marketplace settlement fee','Marketplace platform fee','Deposit fee','Withdrawal fee','Card processor fee','Fee charged to user','Fee recovered from user','Unrecovered fee','Fee subsidy','Failed transaction fee'],'Compare actual cost with collected/recovered amount and net platform exposure.');
