const metric=(label,value,sub,cls='')=>`<article class="metric-card"><div class="metric-label">${esc(label)}</div><div class="metric-value ${cls}">${value}</div><div class="metric-sub">${sub}</div></article>`;
const tag=r=>`<span class="tag ${railClass(r)}">${esc(r)}</span>`;
const status=s=>`<span class="status ${statusTone(s)}">${esc(s)}</span>`;
const amount=v=>v===0?'—':`<span class="${v>0?'amount-positive':'amount-negative'}">${v>0?'+':''}${money(v)}</span>`;
const rowAction=(type,id)=>`<button class="row-action" data-detail="${type}" data-id="${esc(id)}" aria-label="Open details">›</button>`;

function renderActivity(){
  const total=activities.length, financial=activities.filter(a=>['Funding','Purchases','Fees','Treasury'].includes(a.category)).length, exceptions=activities.filter(a=>statusTone(a.status)==='failed').length, active=new Set(activities.filter(a=>a.user).map(a=>a.user)).size;
  document.getElementById('activityMetrics').innerHTML=metric('Events in view',num(total),'All operational + analytics events')+metric('Financial events',num(financial),'Money, credits or fees')+metric('Exceptions',num(exceptions),'Require attention',exceptions?'warning':'positive')+metric('Active users',num(active),'Users represented in current feed');
  const cat=document.getElementById('activityCategory'); if(cat.options.length===1)[...new Set(activities.map(a=>a.category))].sort().forEach(v=>cat.add(new Option(v,v)));
  const rail=document.getElementById('activityRail'); if(rail.options.length===1)[...new Set(activities.map(a=>a.rail))].sort().forEach(v=>rail.add(new Option(v,v)));
  const q=document.getElementById('activitySearch').value.toLowerCase(), c=cat.value, r=rail.value, quick=document.querySelector('#activityQuickFilters .active')?.dataset.filter||'all';
  const rows=activities.filter(a=>(c==='all'||a.category===c)&&(r==='all'||a.rail===r)&&(quick==='all'||a.category===quick)&&Object.values(a).join(' ').toLowerCase().includes(q));
  document.getElementById('activityTable').innerHTML=rows.length?rows.map(a=>`<tr data-detail="event" data-id="${a.id}"><td><span class="cell-primary">${timeAgo(a.mins)}</span><span class="cell-secondary">${stamp(a.mins)}</span></td><td><span class="cell-primary">${esc(a.type)}</span><span class="cell-secondary">${esc(a.category)}</span></td><td><span class="cell-primary">${esc(userName(a.user))}</span><span class="cell-secondary mono">${esc(a.user||'system')}</span></td><td><span class="cell-primary">${esc(a.asset)}</span><span class="cell-secondary mono">${esc(a.ref)}</span></td><td>${amount(a.amount)}</td><td>${tag(a.rail)}</td><td>${status(a.status)}</td><td class="mono">${short(a.corr)}</td><td>${rowAction('event',a.id)}</td></tr>`).join(''):`<tr><td colspan="9" class="empty-state">No events match these filters.</td></tr>`;
}
function initActivityFilters(){const host=document.getElementById('activityQuickFilters');const filters=['all','Funding','Purchases','Reveals','Vault','Marketplace','Stocks','Fees','Shipping','Rewards','Treasury','Reconciliation','Admin','Analytics'];host.innerHTML=filters.map((f,i)=>`<button class="filter-chip ${i===0?'active':''}" data-filter="${f}">${f==='all'?'All activity':f}</button>`).join('');host.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;host.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderActivity()})}

function renderPurchases(){
 const volume=purchases.reduce((s,p)=>s+p.entry,0), stock=purchases.filter(p=>p.kind==='Stocks').length, batches=purchases.filter(p=>p.qty>1).length, bonus=purchases.reduce((s,p)=>s+p.bonus,0);
 document.getElementById('purchaseMetrics').innerHTML=metric('Gross entry volume',money(volume),`${purchases.length} purchase records`)+metric('Stock packs',stock,'Cash-only purchases')+metric('Batch purchases',batches,'Quantity greater than 1')+metric('Crate Bonus issued',`${num(bonus)} cr`,'Non-cash reward units');
 const by={};purchases.forEach(p=>by[p.product]=(by[p.product]||0)+p.entry);renderBars('purchaseBars',Object.entries(by).map(([k,v])=>[k,v,money(v)]));
 const q=document.getElementById('purchaseSearch').value.toLowerCase(); const rows=purchases.filter(p=>Object.values(p).join(' ').toLowerCase().includes(q));
 document.getElementById('purchaseTable').innerHTML=rows.map(p=>`<tr data-detail="purchase" data-id="${p.id}"><td><span class="cell-primary mono">${p.id}</span><span class="cell-secondary">${timeAgo(p.mins)}</span></td><td>${esc(userName(p.user))}</td><td><span class="cell-primary">${esc(p.product)}</span><span class="cell-secondary">${p.kind}</span></td><td>${p.qty}</td><td>${money(p.entry)}</td><td>${tag(p.rail)}</td><td>${num(p.bonus)} cr</td><td>${num(p.xp)}</td><td class="mono">${p.reveal}</td><td>${status(p.status)}</td><td>${rowAction('purchase',p.id)}</td></tr>`).join('');
}
function renderReveals(){
 const exceptions=reveals.filter(r=>r.status==='Exception').length, verified=reveals.filter(r=>r.fair==='Verified').length, avg=reveals.reduce((s,r)=>s+r.fmv,0)/reveals.length, kept=reveals.filter(r=>/Vault|List|Hold stock/i.test(r.decision)).length;
 document.getElementById('revealMetrics').innerHTML=metric('Verified reveals',verified,`${Math.round(verified/reveals.length*100)}% of shown reveals`,'positive')+metric('Exceptions',exceptions,'Paused or manual review','warning')+metric('Average reveal FMV',money(avg),'Snapshot at reveal')+metric('Kept / held',kept,'Moved into vault or portfolio');
 const q=document.getElementById('revealSearch').value.toLowerCase(), only=document.getElementById('onlyExceptions').classList.contains('active'); const rows=reveals.filter(r=>(!only||r.status==='Exception')&&Object.values(r).join(' ').toLowerCase().includes(q));
 document.getElementById('revealTable').innerHTML=rows.map(r=>`<tr data-detail="reveal" data-id="${r.id}"><td><span class="cell-primary mono">${r.id}</span><span class="cell-secondary">${timeAgo(r.mins)}</span></td><td>${esc(userName(r.user))}</td><td>${esc(r.pack)}</td><td><span class="cell-primary">${esc(r.outcome)}</span><span class="cell-secondary">${esc(r.rarity)}</span></td><td>${money(r.fmv)}</td><td>${esc(r.decision)}</td><td>${status(r.fair)}</td><td>${r.flags==='—'?'<span class="cell-secondary">—</span>':`<span class="status pending">${esc(r.flags)}</span>`}</td><td>${status(r.status)}</td><td>${rowAction('reveal',r.id)}</td></tr>`).join('');
}
function renderMarket(){
 const active=marketEvents.filter(e=>e.kind==='Listing'&&e.status==='Active').length, offers=marketEvents.filter(e=>e.kind==='Offer').length, sale=marketEvents.filter(e=>e.kind==='Sale'||/Seller proceeds|Buy Now/i.test(e.action)).reduce((s,e)=>s+e.value,0), feesTotal=marketEvents.reduce((s,e)=>s+e.fee,0);
 document.getElementById('marketMetrics').innerHTML=metric('Active listing events',active,'Including offer-only states')+metric('Offer events',offers,'Sent, accepted, declined, countered')+metric('Sale volume',money(sale),'Gross source volume')+metric('Platform fees',money(feesTotal),'Chosen revenue from shown sales');
 const f=document.querySelector('#marketFilter .active')?.dataset.filter||'all';const rows=marketEvents.filter(e=>f==='all'||e.kind===f);document.getElementById('marketTable').innerHTML=rows.map((e,i)=>`<tr data-detail="market" data-id="${i}"><td>${timeAgo(e.mins)}</td><td><span class="cell-primary">${e.action}</span><span class="cell-secondary">${e.kind}</span></td><td>${e.item}</td><td>${esc(userName(e.actor))}</td><td>${esc(userName(e.counter))}</td><td>${e.value?money(e.value):'—'}</td><td>${e.fee?money(e.fee):'—'}</td><td>${status(e.status)}</td><td class="mono">${short(e.corr)}</td><td>${rowAction('market',i)}</td></tr>`).join('');
}
function renderPortfolios(){
 const stock=users.reduce((s,u)=>s+u.stocks,0), vault=users.reduce((s,u)=>s+u.vaultValue,0), basis=users.reduce((s,u)=>s+u.stockCost,0), pnl=stock-basis, pending=users.reduce((s,u)=>s+u.pending,0);
 document.getElementById('portfolioMetrics').innerHTML=metric('Stock value',money(stock),'User-owned positions')+metric('Unrealized stock P&L',money(pnl),'Value minus acquisition basis',pnl>=0?'positive':'negative')+metric('Vault market value',money(vault),'Physical collectible holdings')+metric('Pending vault exposure',money(pending),'70% capped liquidation planning exposure');
 const q=document.getElementById('portfolioSearch').value.toLowerCase(); const rows=users.filter(u=>Object.values(u).join(' ').toLowerCase().includes(q));document.getElementById('portfolioGrid').innerHTML=rows.map(u=>{const total=u.cash+u.usdc+u.stocks+u.vaultValue;return `<article class="portfolio-card" data-detail="user" data-id="${u.id}"><div class="user-row"><div class="user-avatar">${initials(u.name)}</div><div class="user-meta"><strong>${u.name}</strong><span>${u.handle} · ${u.id}</span></div><div class="user-total"><strong>${money(total)}</strong><span>tracked value</span></div></div><div class="portfolio-mini-grid"><div class="mini-balance"><span>Cash</span><strong>${money(u.cash)}</strong></div><div class="mini-balance"><span>USDC</span><strong>${money(u.usdc)}</strong></div><div class="mini-balance"><span>Credits</span><strong>${num(u.credits)} cr</strong></div><div class="mini-balance"><span>Stocks</span><strong>${money(u.stocks)}</strong></div><div class="mini-balance"><span>Vault</span><strong>${money(u.vaultValue)}</strong></div><div class="mini-balance"><span>Pending exposure</span><strong>${money(u.pending)}</strong></div></div></article>`}).join('');
}
function renderWallets(){
 const totalCash=users.reduce((s,u)=>s+u.cash,0), totalUsdc=users.reduce((s,u)=>s+u.usdc,0), deposits=walletEvents.filter(e=>e.amount>0&&/deposit/i.test(e.action)).reduce((s,e)=>s+e.amount,0), withdrawals=Math.abs(walletEvents.filter(e=>e.amount<0).reduce((s,e)=>s+e.amount,0)), failures=walletEvents.filter(e=>statusTone(e.status)==='failed').length;
 document.getElementById('walletMetrics').innerHTML=metric('User Cash balances',money(totalCash),'Tracked account cash')+metric('User USDC balances',money(totalUsdc),'Tracked stablecoin balances')+metric('Deposits shown',money(deposits),'Gross successful/pending deposit intents')+metric('Withdrawal volume',money(withdrawals),`${failures} failed payment event${failures===1?'':'s'}`);
 renderBars('walletBars',[['Cash movement',walletEvents.filter(x=>x.rail==='Cash').reduce((s,x)=>s+Math.abs(x.amount),0),'Cash'],['USDC movement',walletEvents.filter(x=>x.rail==='USDC').reduce((s,x)=>s+Math.abs(x.amount),0),'USDC'],['Fees',walletEvents.reduce((s,x)=>s+x.fee,0),'Actual fees']]);
 const q=document.getElementById('walletSearch').value.toLowerCase();document.getElementById('walletTable').innerHTML=walletEvents.filter(e=>Object.values(e).join(' ').toLowerCase().includes(q)).map((e,i)=>`<tr data-detail="wallet" data-id="${i}"><td>${timeAgo(e.mins)}</td><td>${e.action}</td><td>${userName(e.user)}</td><td>${tag(e.rail)}</td><td>${e.provider}</td><td>${amount(e.amount)}</td><td>${e.fee?money(e.fee):'—'}</td><td class="mono">${short(e.ref)}</td><td>${status(e.status)}</td><td>${rowAction('wallet',i)}</td></tr>`).join('');
}
function renderFees(){
 const cost=fees.reduce((s,f)=>s+f.cost,0), collected=fees.reduce((s,f)=>s+f.userFee,0), recovered=fees.reduce((s,f)=>s+f.recovered,0), exposure=Math.max(0,cost-recovered), coverage=cost?recovered/cost*100:100;
 document.getElementById('feeMetrics').innerHTML=metric('Actual transaction cost',money(cost,4),'Successful + failed')+metric('Fees charged to users',money(collected,4),'Configured fee amount')+metric('Cost recovered',money(recovered,4),`${pct(coverage)} of actual cost`,'positive')+metric('Net platform exposure',money(exposure,4),'Actual cost not recovered',exposure?'warning':'positive');
 const by={};fees.forEach(f=>by[f.network]=(by[f.network]||0)+f.cost);renderBars('feeNetworkBars',Object.entries(by).map(([k,v])=>[k,v,money(v,4)]));document.getElementById('coveragePct').textContent=pct(coverage);document.getElementById('coverageRing').style.setProperty('--pct',`${Math.min(360,coverage*3.6)}deg`);document.getElementById('coverageRecovered').textContent=`${money(recovered,4)} recovered`;document.getElementById('coverageExposure').textContent=`${money(exposure,4)} net platform exposure`;
 const q=document.getElementById('feeSearch').value.toLowerCase();document.getElementById('feeTable').innerHTML=fees.filter(f=>Object.values(f).join(' ').toLowerCase().includes(q)).map((f,i)=>{const net=Math.max(0,f.cost-f.recovered);return `<tr data-detail="fee" data-id="${i}"><td>${timeAgo(f.mins)}</td><td>${f.action}</td><td>${userName(f.user)}</td><td>${f.network}</td><td>${money(f.notional)}</td><td>${money(f.cost,4)}</td><td>${money(f.userFee,4)}</td><td>${money(f.recovered,4)}</td><td class="${net?'amount-negative':'amount-positive'}">${money(net,4)}</td><td>${status(f.status)}</td><td>${rowAction('fee',i)}</td></tr>`}).join('');
}
function renderRewards(){
 const circulation=users.reduce((s,u)=>s+u.credits,0), spend=rewardEvents.filter(e=>e.dir==='Out').reduce((s,e)=>s+e.amount,0), back=rewardEvents.filter(e=>/Credit Back/i.test(e.event)).reduce((s,e)=>s+e.amount,0), emissions=rewardEvents.filter(e=>e.dir==='In'&&!/Credit Back/i.test(e.event)).reduce((s,e)=>s+e.amount,0);
 document.getElementById('rewardMetrics').innerHTML=metric('Credits in shown accounts',`${num(circulation)} cr`,'Non-cash units')+metric('Credit Spend',`${num(spend)} cr`,'Credits removed')+metric('Credit Back',`${num(back)} cr`,'Outcome settlement')+metric('New emissions',`${num(emissions)} cr`,'Bonus, referral, Lulu, promos, tasks');
 const types={};rewardEvents.forEach(e=>types[e.event]=(types[e.event]||0)+e.amount);renderBars('rewardBars',Object.entries(types).filter(([,v])=>v>0).map(([k,v])=>[k,v,`${num(v)} cr`]));
 const q=document.getElementById('rewardSearch').value.toLowerCase();document.getElementById('rewardTable').innerHTML=rewardEvents.filter(e=>Object.values(e).join(' ').toLowerCase().includes(q)).map((e,i)=>`<tr data-detail="reward" data-id="${i}"><td>${timeAgo(e.mins)}</td><td>${e.event}</td><td>${userName(e.user)}</td><td>${e.dir}</td><td>${e.amount?`${e.dir==='Out'?'-':'+'}${num(e.amount)} cr`:'—'}</td><td>${num(e.balance)} cr</td><td class="mono">${e.ref}</td><td>${status(e.status)}</td><td>${rowAction('reward',i)}</td></tr>`).join('');
}
function renderRecon(){
 const mismatch=recon.filter(r=>r.result==='Mismatch').length, high=recon.filter(r=>r.severity==='High').length, matched=recon.filter(r=>r.result==='Matched').length;
 document.getElementById('reconMetrics').innerHTML=metric('Checks run',recon.length,'Across core sources of truth')+metric('Matched',matched,'No difference','positive')+metric('Mismatches',mismatch,'Require investigation',mismatch?'warning':'positive')+metric('High severity',high,'Immediate attention',high?'negative':'positive');
 const q=document.getElementById('reconSearch').value.toLowerCase();document.getElementById('reconTable').innerHTML=recon.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)).map((r,i)=>`<tr data-detail="recon" data-id="${i}"><td>${timeAgo(r.mins)}</td><td>${r.scope}</td><td>${r.internal}</td><td>${r.observed}</td><td>${r.diff}</td><td>${r.severity}</td><td>${status(r.result)}</td><td class="mono">${r.ref}</td><td>${rowAction('recon',i)}</td></tr>`).join('');
}
function renderCatalog(){
 const domain=document.getElementById('catalogDomain');if(domain.options.length===1)[...new Set(eventCatalog.map(e=>e.domain))].sort().forEach(v=>domain.add(new Option(v,v)));const q=document.getElementById('catalogSearch').value.toLowerCase(),d=domain.value,l=document.getElementById('catalogLevel').value;const rows=eventCatalog.filter(e=>(d==='all'||e.domain===d)&&(l==='all'||e.level===l)&&Object.values(e).join(' ').toLowerCase().includes(q));document.getElementById('catalogCount').textContent=`${rows.length} of ${eventCatalog.length} event types`;document.getElementById('catalogGrid').innerHTML=rows.map(e=>`<article class="catalog-card"><div class="catalog-card-head"><span class="catalog-domain">${e.domain}</span><span class="status level-${e.level.toLowerCase()}">${e.level}</span></div><h3>${e.name}</h3><p>${e.description}</p><div class="catalog-meta"><span class="tag internal">correlation_id</span><span class="tag internal">user_id</span><span class="tag internal">reference</span></div></article>`).join('');
}
function renderBars(id,rows){const max=Math.max(1,...rows.map(r=>r[1]));document.getElementById(id).innerHTML=rows.sort((a,b)=>b[1]-a[1]).map(r=>`<div class="bar-row"><div class="bar-label"><strong>${esc(r[0])}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,r[1]/max*100)}%"></div></div><div class="bar-value">${esc(r[2])}</div></div>`).join('')}
const initials=n=>n.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();

function openDrawer(type,id){
 let title='Details',eyebrow=type.toUpperCase(),body='';
 if(type==='event'){const a=activities.find(x=>x.id===id);if(!a)return;title=a.type;eyebrow=a.category;body=eventDrawer(a)}
 if(type==='purchase'){const p=purchases.find(x=>x.id===id);if(!p)return;title=p.id;eyebrow='PURCHASE';body=objectDrawer(p,`Purchase · ${p.product}`,p.corr)}
 if(type==='reveal'){const r=reveals.find(x=>x.id===id);if(!r)return;title=r.id;eyebrow='REVEAL';body=objectDrawer(r,`${r.outcome} · ${r.decision}`,r.corr)}
 if(type==='market'){const e=marketEvents[Number(id)];if(!e)return;title=e.action;eyebrow='SECONDARY MARKET';body=objectDrawer(e,e.item,e.corr)}
 if(type==='wallet'){const e=walletEvents[Number(id)];if(!e)return;title=e.action;eyebrow='WALLET';body=objectDrawer(e,userName(e.user))}
 if(type==='fee'){const e=fees[Number(id)];if(!e)return;title=e.action;eyebrow='FEE';body=objectDrawer(e,`Actual cost ${money(e.cost,4)}`,e.corr)}
 if(type==='reward'){const e=rewardEvents[Number(id)];if(!e)return;title=e.event;eyebrow='REWARD';body=objectDrawer(e,userName(e.user))}
 if(type==='recon'){const e=recon[Number(id)];if(!e)return;title=e.scope;eyebrow='RECONCILIATION';body=objectDrawer(e,`${e.result} · ${e.diff}`)}
 if(type==='user'){const u=userById[id];if(!u)return;title=u.name;eyebrow='USER PORTFOLIO';body=userDrawer(u)}
 document.getElementById('drawerTitle').textContent=title;document.getElementById('drawerEyebrow').textContent=eyebrow;document.getElementById('drawerBody').innerHTML=body;document.getElementById('detailDrawer').classList.add('open');document.getElementById('drawerBackdrop').classList.add('open');document.getElementById('detailDrawer').setAttribute('aria-hidden','false');
}
function kv(k,v){return `<div class="detail-kv"><span>${esc(k)}</span><strong>${esc(v??'—')}</strong></div>`}
function eventDrawer(a){const u=userById[a.user];const related=activities.filter(x=>x.corr===a.corr).sort((x,y)=>y.mins-x.mins);return `${u?`<div class="drawer-section"><div class="drawer-user-head"><div class="user-avatar">${initials(u.name)}</div><div><strong>${u.name}</strong><span>${u.id} · ${u.wallet}</span></div></div></div>`:''}<div class="drawer-section"><div class="drawer-section-title">Event</div><div class="detail-grid">${kv('Event ID',a.id)}${kv('Category',a.category)}${kv('Reference',a.ref)}${kv('Correlation ID',a.corr)}${kv('Rail',a.rail)}${kv('Status',a.status)}${kv('Amount',a.amount?money(a.amount):'—')}${kv('Direct fee',a.fee?money(a.fee,4):'—')}</div><div class="detail-note">${esc(a.note)}</div></div>${timelineDrawer(related)}`}
function objectDrawer(o,headline,corr){const entries=Object.entries(o).filter(([k])=>!['note'].includes(k));const related=corr?activities.filter(x=>x.corr===corr).sort((a,b)=>b.mins-a.mins):[];return `<div class="drawer-section"><div class="drawer-section-title">${esc(headline)}</div><div class="detail-grid">${entries.map(([k,v])=>kv(k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()),typeof v==='number'&&/amount|entry|fmv|fee|value|cost|notional/i.test(k)?money(v):v)).join('')}</div>${o.note?`<div class="detail-note">${esc(o.note)}</div>`:''}</div>${related.length?timelineDrawer(related):''}`}
function timelineDrawer(rows){return `<div class="drawer-section"><div class="drawer-section-title">Correlation timeline · ${rows[0]?.corr||'—'}</div><div class="timeline">${rows.map(r=>`<div class="timeline-row"><strong>${esc(r.type)}</strong><span>${timeAgo(r.mins)} · ${esc(r.ref)} · ${esc(r.status)}</span></div>`).join('')}</div></div>`}
function userDrawer(u){const pos=positions[u.id]||[],events=activities.filter(a=>a.user===u.id).slice(0,10);return `<div class="drawer-section"><div class="drawer-user-head"><div class="user-avatar">${initials(u.name)}</div><div><strong>${u.name}</strong><span>${u.handle} · ${u.id}<br>${u.wallet}</span></div></div></div><div class="drawer-section"><div class="drawer-section-title">Balances & ownership</div><div class="detail-grid">${kv('Cash',money(u.cash))}${kv('USDC',money(u.usdc))}${kv('Credits',`${num(u.credits)} cr`)}${kv('Stocks',money(u.stocks))}${kv('Stock cost basis',money(u.stockCost))}${kv('Vault market value',money(u.vaultValue))}${kv('Inventory items',u.inventory)}${kv('Pending exposure',money(u.pending))}</div></div><div class="drawer-section"><div class="drawer-section-title">Stock positions</div>${pos.length?`<div class="timeline">${pos.map(p=>`<div class="timeline-row"><strong>${p[0]} · ${p[1]} sh · ${money(p[2])}</strong><span>Acquisition basis ${money(p[3])} · unrealized ${money(p[2]-p[3])}</span></div>`).join('')}</div>`:'<div class="detail-note">No stock positions.</div>'}</div><div class="drawer-section"><div class="drawer-section-title">Recent account activity</div><div class="timeline">${events.map(e=>`<div class="timeline-row"><strong>${e.type}</strong><span>${timeAgo(e.mins)} · ${e.ref}</span></div>`).join('')}</div></div>`}
function closeDrawer(){document.getElementById('detailDrawer').classList.remove('open');document.getElementById('drawerBackdrop').classList.remove('open');document.getElementById('detailDrawer').setAttribute('aria-hidden','true')}

const renderers={activity:renderActivity,purchases:renderPurchases,reveals:renderReveals,market:renderMarket,portfolios:renderPortfolios,wallets:renderWallets,fees:renderFees,rewards:renderRewards,recon:renderRecon,catalog:renderCatalog};
function showView(name){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));const view=document.getElementById(`view-${name}`);document.getElementById('pageTitle').textContent=view.dataset.title;document.getElementById('sectionEyebrow').textContent=view.dataset.eyebrow;renderers[name]?.();document.getElementById('sidebar').classList.remove('open');}
function csvEscape(v){const s=String(v??'');return /[",\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s}
function exportCurrent(){const active=document.querySelector('.view.active');const rows=[...active.querySelectorAll('table tr')].map(tr=>[...tr.querySelectorAll('th,td')].slice(0,-1).map(c=>csvEscape(c.innerText.trim())).join(','));const blob=new Blob([rows.join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`observe-${active.id.replace('view-','')}.csv`;a.click();URL.revokeObjectURL(a.href);toast('CSV exported')}
let toastTimer;function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}

function wire(){
 document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
 document.getElementById('openSidebar').addEventListener('click',()=>document.getElementById('sidebar').classList.add('open'));document.getElementById('closeSidebar').addEventListener('click',()=>document.getElementById('sidebar').classList.remove('open'));
 document.getElementById('closeDrawer').addEventListener('click',closeDrawer);document.getElementById('drawerBackdrop').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
 document.addEventListener('click',e=>{const x=e.target.closest('[data-detail]');if(!x)return;openDrawer(x.dataset.detail,x.dataset.id)});
 document.getElementById('exportButton').addEventListener('click',exportCurrent);
 document.getElementById('activitySearch').addEventListener('input',renderActivity);document.getElementById('activityCategory').addEventListener('change',renderActivity);document.getElementById('activityRail').addEventListener('change',renderActivity);
 document.getElementById('purchaseSearch').addEventListener('input',renderPurchases);document.getElementById('revealSearch').addEventListener('input',renderReveals);document.getElementById('onlyExceptions').addEventListener('click',e=>{e.currentTarget.classList.toggle('active');e.currentTarget.textContent=e.currentTarget.classList.contains('active')?'Show all reveals':'Show exceptions';renderReveals()});
 document.getElementById('marketFilter').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('#marketFilter button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderMarket()});
 document.getElementById('portfolioSearch').addEventListener('input',renderPortfolios);document.getElementById('walletSearch').addEventListener('input',renderWallets);document.getElementById('feeSearch').addEventListener('input',renderFees);document.getElementById('rewardSearch').addEventListener('input',renderRewards);document.getElementById('reconSearch').addEventListener('input',renderRecon);document.getElementById('catalogSearch').addEventListener('input',renderCatalog);document.getElementById('catalogDomain').addEventListener('change',renderCatalog);document.getElementById('catalogLevel').addEventListener('change',renderCatalog);
 document.getElementById('runRecon').addEventListener('click',()=>{toast('Reconciliation checks completed');renderRecon()});
 const global=document.getElementById('globalSearch');global.addEventListener('keydown',e=>{if(e.key!=='Enter')return;showView('activity');document.getElementById('activitySearch').value=global.value;renderActivity()});
}

initActivityFilters();wire();Object.values(renderers).forEach(fn=>fn());document.getElementById('lastUpdated').textContent='just now';setInterval(()=>{document.getElementById('lastUpdated').textContent='just now'},15000);
